`timescale 1ns/1ps
// ============================================================================
// tb_emu_preview.v - GENERATED by application/emulator-preview/gen_emu_preview.py
// from emu_commands.txt; do not edit.
//
// EMULATOR PREVIEW: the ./emu command lines below, played on the chip `top`
// in simulation exactly as the organisers' emulator performs them, printing
// the lines emu prints. Each line is one run: reset, then the options in order;
// the run stops at the first comparison that fails, as emu does.
//
//    1  README example as written: -o before the echo reads 0x00, emu stops there   (emu is expected to stop at -o)
//    2  Same test with -o after the echo: every comparison passes
//    3  The README's test values: 0xA on P3-P0, 0x30 through the UART
//    4  Four bytes in one option, echoed one by one, least-significant byte first
//
// LINE = 0 plays every line; LINE = k plays line k only.
// Pass: "EMULATOR PREVIEW: ALL TESTS PASSED".
// ============================================================================
module testbench;
    parameter LINE = 0;
    localparam integer NB      = 263;      // clock cycles per UART bit: 115200 bps at 30.303 MHz
    localparam integer GAP     = 20000;    // silence after each emu access (emu: ~0.1 s)
    localparam integer BOOT    = 3000;     // after reset, before the first access
    localparam integer TIMEOUT = 400000;   // the longest a -r may wait for its bytes
    localparam integer N_EV    = 86;
    localparam integer N_RUNS  = 4;

    reg clk = 1'b0, rst = 1'b1;
    always #16.5 clk = ~clk;
    integer cycles = 0;
    always @(posedge clk) cycles = cycles + 1;

    // the emulator's side of the pins: it drives pin k with emu_in[k] while
    // emu_dir[k] = 0, and observes it while emu_dir[k] = 1
    reg  [7:0] emu_dir = 8'h01, emu_in = 8'h00;
    reg        uart_rx = 1'b1;
    wire       uart_tx;
    wire [7:0] pins;
    genvar g;
    generate for (g = 0; g < 8; g = g + 1) begin : pin
        assign pins[g] = emu_dir[g] ? 1'bz : emu_in[g];
        assign (weak0, weak1) pins[g] = 1'b0;
    end endgenerate
    top dut (
        .clk_i(clk), .rst_i(rst),
        .pins_io_0(pins[0]), .pins_io_1(pins[1]), .pins_io_2(pins[2]), .pins_io_3(pins[3]),
        .pins_io_4(pins[4]), .pins_io_5(pins[5]), .pins_io_6(pins[6]), .pins_io_7(pins[7]),
        .tx_o(uart_tx), .rx_i(uart_rx));

    initial begin
        $dumpfile("testbench.vcd");
        $dumpvars(1, testbench);
    end

    reg [7:0] ev [0:85];
    initial begin
        ev[0]=8'h53; ev[1]=8'h01; ev[2]=8'h4f; ev[3]=8'h44; ev[4]=8'h01; ev[5]=8'hf0; ev[6]=8'h49; ev[7]=8'h01; ev[8]=8'h02; ev[9]=8'h4f; ev[10]=8'h01; ev[11]=8'h20;
        ev[12]=8'h54; ev[13]=8'h01; ev[14]=8'h30; ev[15]=8'h52; ev[16]=8'h01; ev[17]=8'h30; ev[18]=8'h45; ev[19]=8'h00; ev[20]=8'h53; ev[21]=8'h01; ev[22]=8'h00; ev[23]=8'h44;
        ev[24]=8'h01; ev[25]=8'hf0; ev[26]=8'h49; ev[27]=8'h01; ev[28]=8'h02; ev[29]=8'h54; ev[30]=8'h01; ev[31]=8'h30; ev[32]=8'h52; ev[33]=8'h01; ev[34]=8'h30; ev[35]=8'h4f;
        ev[36]=8'h01; ev[37]=8'h20; ev[38]=8'h45; ev[39]=8'h00; ev[40]=8'h53; ev[41]=8'h01; ev[42]=8'h00; ev[43]=8'h44; ev[44]=8'h01; ev[45]=8'hf0; ev[46]=8'h49; ev[47]=8'h01;
        ev[48]=8'h0a; ev[49]=8'h54; ev[50]=8'h01; ev[51]=8'h30; ev[52]=8'h52; ev[53]=8'h01; ev[54]=8'h30; ev[55]=8'h4f; ev[56]=8'h01; ev[57]=8'ha0; ev[58]=8'h45; ev[59]=8'h00;
        ev[60]=8'h53; ev[61]=8'h01; ev[62]=8'h00; ev[63]=8'h44; ev[64]=8'h01; ev[65]=8'hf0; ev[66]=8'h49; ev[67]=8'h01; ev[68]=8'h05; ev[69]=8'h54; ev[70]=8'h04; ev[71]=8'h00;
        ev[72]=8'hff; ev[73]=8'ha5; ev[74]=8'h5a; ev[75]=8'h52; ev[76]=8'h04; ev[77]=8'h00; ev[78]=8'hff; ev[79]=8'ha5; ev[80]=8'h5a; ev[81]=8'h4f; ev[82]=8'h01; ev[83]=8'h50;
        ev[84]=8'h45; ev[85]=8'h00;
    end

    // the emulator's UART receive buffer: the first 8 bytes the chip sends
    reg [7:0] rxbuf [0:7];
    integer   rx_n = 0;
    reg [7:0] rb;
    integer   rk;
    always begin
        @(negedge uart_tx);
        if (rst === 1'b0) begin
            repeat (NB / 2) @(posedge clk);
            for (rk = 0; rk < 8; rk = rk + 1) begin repeat (NB) @(posedge clk); rb[rk] = uart_tx; end
            repeat (NB) @(posedge clk);
            if (rx_n < 8) rxbuf[rx_n] = rb;
            rx_n = rx_n + 1;
        end
    end

    task uart_send(input [7:0] b);
        integer j;
        begin
            uart_rx = 1'b0; repeat (NB) @(posedge clk);
            for (j = 0; j < 8; j = j + 1) begin uart_rx = b[j]; repeat (NB) @(posedge clk); end
            uart_rx = 1'b1; repeat (NB) @(posedge clk);
        end
    endtask

    // upper-case hex of the low n bytes of v, as emu prints it
    function [8*8-1:0] hexs(input [31:0] v, input integer n);
        integer d;
        reg [3:0] q;
        begin
            hexs = 0;
            for (d = 2 * n - 1; d >= 0; d = d - 1) begin
                q = v >> (4 * d);
                hexs = {hexs[8*7-1:0], (q < 10) ? (8'd48 + q) : (8'd55 + q)};
            end
        end
    endfunction

    task show_cmd(input integer k);
        case (k)
            0: begin $display(""); $display("-- 1. README example as written: -o before the echo reads 0x00, emu stops there"); $display("$ ./emu -d 0xF0 -i 0x02 -o 0x20 -t1 0x30 -r1 0x30"); end
            1: begin $display(""); $display("-- 2. Same test with -o after the echo: every comparison passes"); $display("$ ./emu -d 0xF0 -i 0x02 -t1 0x30 -r1 0x30 -o 0x20"); end
            2: begin $display(""); $display("-- 3. The README's test values: 0xA on P3-P0, 0x30 through the UART"); $display("$ ./emu -d 0xF0 -i 0x0A -t1 0x30 -r1 0x30 -o 0xA0"); end
            3: begin $display(""); $display("-- 4. Four bytes in one option, echoed one by one, least-significant byte first"); $display("$ ./emu -d 0xF0 -i 0x05 -t4 0x5AA5FF00 -r4 0x5AA5FF00 -o 0x50"); end
        endcase
    endtask

    integer i, k, n, t, ptr, run = 0, pass = 0, fail = 0;
    reg [31:0] v, got;
    reg [8*8-1:0] hs, he;
    reg [7:0]  op, expect;
    reg        stopped, started;
    initial begin
        $display("============================================================");
        $display(" Emulator preview: ./emu command lines played on RVBL-2");
        $display(" UART 115200 bps, %0d cycles of silence after each emu access", GAP);
        $display("============================================================");
        i = 0;
        while (i < N_EV) begin
            op = ev[i]; n = ev[i + 1];
            v = 0;
            for (k = 0; k < n; k = k + 1) v = v | (ev[i + 2 + k] << (8 * k));
            if (op == "S") begin                     // a new emu run
                expect = ev[i + 2];
                stopped = 1'b0; started = 1'b0;
                if (LINE != 0 && LINE != run + 1) begin    // skip to this run's end
                    while (ev[i] != "E") i = i + 2 + ev[i + 1];
                    stopped = 1'b1; n = -2;                // so the loop lands on the E
                end else begin
                    show_cmd(run);
                    rst = 1'b1; emu_dir = 8'h01; emu_in = 8'h00; rx_n = 0; ptr = 0;
                    repeat (20) @(posedge clk);
                    $display("[ok] RISC-V started!");
                end
            end else if (op == "E") begin
                if (!(LINE != 0 && LINE != run + 1)) begin
                    if (expect != 0 && !stopped) begin
                        fail = fail + 1;
                        $display("FAIL line %0d: emu was expected to stop at -%s, but every comparison passed", run + 1, expect == "O" ? "o" : "r");
                    end else if (expect == 0 && stopped) begin
                        fail = fail + 1;
                        $display("FAIL line %0d", run + 1);
                    end else begin
                        pass = pass + 1;
                        if (expect != 0) $display("PASS line %0d: emu stops at -%s, as expected", run + 1, expect == "O" ? "o" : "r");
                        else             $display("PASS line %0d", run + 1);
                    end
                end
                run = run + 1;
            end else if (!stopped) begin
                // emu's first -d comes before the core runs its first instruction here; on
                // the F2 it follows the reset (the firmware sets its own pin directions)
                if (!started && op != "D") begin
                    started = 1'b1;
                    rst = 1'b0; repeat (BOOT) @(posedge clk);
                end
                case (op)
                    "D": begin emu_dir = v; $display("[ok] Written 0x%s to DIRECTION", hexs(v, 4)); end
                    "I": begin emu_in = v; $display("[ok] Written 0x%s to INPUT PINS", hexs(v, 4));
                               repeat (GAP) @(posedge clk); end
                    "T": begin
                        for (k = 0; k < n; k = k + 1) begin uart_send(ev[i + 2 + k]); repeat (GAP) @(posedge clk); end
                        hs = hexs(v, n);
                        case (n) 1: $display("[ok] Written 0x%s to UART RX", hs[15:0]);
                                 2: $display("[ok] Written 0x%s to UART RX", hs[31:0]);
                           default: $display("[ok] Written 0x%s to UART RX", hs); endcase
                    end
                    "R": begin
                        t = 0;
                        while (rx_n < ptr + n && t < TIMEOUT) begin @(posedge clk); t = t + 1; end
                        got = 0;
                        for (k = 0; k < n; k = k + 1)
                            if (ptr + k < rx_n && ptr + k < 8) got = got | (rxbuf[ptr + k] << (8 * k));
                        ptr = ptr + n;
                        hs = hexs(got, n); he = hexs(v, n);
                        if (got === v) case (n)
                            1: $display("[ok] Read 0x%s from UART TX", hs[15:0]);
                            2: $display("[ok] Read 0x%s from UART TX", hs[31:0]);
                            default: $display("[ok] Read 0x%s from UART TX", hs);
                        endcase else begin
                            case (n)
                                1: $display("[error] UART read error. Expected 0x%s. Got 0x%s", he[15:0], hs[15:0]);
                                2: $display("[error] UART read error. Expected 0x%s. Got 0x%s", he[31:0], hs[31:0]);
                                default: $display("[error] UART read error. Expected 0x%s. Got 0x%s", he, hs);
                            endcase
                            stopped = 1'b1;
                        end
                    end
                    "O": begin
                        repeat (GAP) @(posedge clk);
                        got = {24'd0, pins & emu_dir};
                        if (got === v) $display("[ok] Read 0x%s from OUTPUT PINS", hexs(got, 4));
                        else begin
                            $display("[error] OUT read error. Expected 0x%s. Got 0x%s", hexs(v, 4), hexs(got, 4));
                            stopped = 1'b1;
                        end
                    end
                endcase
                if (stopped && expect != 0 && expect != op) begin
                    $display("(stopped at -%s, not at the expected -%s)", op == "O" ? "o" : "r", expect == "O" ? "o" : "r");
                    expect = 0;                          // counts as a failure at E
                end
            end
            i = i + 2 + n;
        end
        $display("");
        $display("==== tb_emu_preview: %0d passed, %0d failed ====", pass, fail);
        if (fail == 0) $display("EMULATOR PREVIEW: ALL TESTS PASSED");
        else           $display("EMULATOR PREVIEW: FAILURES PRESENT");
        $finish;
    end
endmodule
